import{_ as t,o as a,c as o,a2 as n}from"./chunks/framework.mRCPFc5l.js";const u=JSON.parse('{"title":"Kanban","description":"Display entries as cards in columns and move them via drag and drop.","frontmatter":{"title":"Kanban","description":"Display entries as cards in columns and move them via drag and drop."},"headers":[],"relativePath":"en/ansichten/kanban.md","filePath":"en/ansichten/kanban.md","lastUpdated":1787319236000}'),r={name:"en/ansichten/kanban.md"};function i(s,e,l,d,c,h){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="kanban" tabindex="-1">Kanban <a class="header-anchor" href="#kanban" aria-label="Permalink to &quot;Kanban&quot;">​</a></h1><p>A <strong>Kanban board</strong> shows entries as cards in columns. Cards can be moved via drag and drop — which changes the underlying field value.</p><p>The interface describes it as <em>An overview of your workflows</em>.</p><p><strong>Suited for:</strong> workflows with clear stages — applications, tickets, tasks, sales opportunities, approval processes.</p><h2 id="requirement-a-single-select-column" tabindex="-1">Requirement: a Single Select column <a class="header-anchor" href="#requirement-a-single-select-column" aria-label="Permalink to &quot;Requirement: a Single Select column&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">No board without Single Select</p><blockquote><p><em>To see a Kanban board, your Grid needs a column of type Single Select. Each option represents one column of the Kanban board.</em></p></blockquote><p>If such a column is missing, ApptiveGrid offers <strong>Create field</strong> to add it directly.</p></div><p>Every <strong>option</strong> of the Single Select becomes a <strong>column</strong> of the board. A status field with <code>New</code>, <code>In progress</code>, <code>Done</code> results in three columns.</p><div class="tip custom-block"><p class="custom-block-title">Options are the columns — in that order</p><p>The order of the columns follows the order of the options in the field. To reorder the columns, change the option order in the Grid&#39;s field settings.</p><p>Note: this affects <strong>every</strong> view and form using this field.</p></div><h2 id="create-a-board" tabindex="-1">Create a board <a class="header-anchor" href="#create-a-board" aria-label="Permalink to &quot;Create a board&quot;">​</a></h2><ol><li>Under the Grid, choose <strong>Create view</strong>.</li><li>Choose <strong>Kanban</strong>.</li><li>Set the grouping field via <strong>Grouped by</strong>.</li></ol><p>The picker dialog is called <em>Choose a grouping field</em>, with the note <em>Each option represents one column of the Kanban board</em>.</p><h2 id="moving-cards" tabindex="-1">Moving cards <a class="header-anchor" href="#moving-cards" aria-label="Permalink to &quot;Moving cards&quot;">​</a></h2><p>Drag a card into another column — the value of the grouping field changes immediately.</p><div class="warning custom-block"><p class="custom-block-title">This changes real data</p><p>A moved card is a changed row in the Grid. If a <a href="/en/flows/trigger">flow</a> with the <em>Entry was changed</em> trigger is attached to this field, it starts when you do this.</p><p>That&#39;s usually intentional — for example, a notification when something switches to <code>Done</code>. But when cleaning up a board, it can lead to unwanted mass triggers.</p></div><h2 id="ungrouped-cards" tabindex="-1">Ungrouped cards <a class="header-anchor" href="#ungrouped-cards" aria-label="Permalink to &quot;Ungrouped cards&quot;">​</a></h2><p>Entries with no value in the grouping field belong to no column. They collect under <strong>UNGROUPED</strong>.</p><p>Use <strong>Show ungrouped cards</strong> and <strong>Hide ungrouped cards</strong> to control their display.</p><div class="tip custom-block"><p class="custom-block-title">The board&#39;s inbox</p><p>Entries coming in via a <a href="/en/formulare/formular-erstellen">form</a> often have no status yet and land under <em>UNGROUPED</em>. That works well as an inbox — everything sitting there hasn&#39;t been sorted yet.</p><p>Alternatively, set a default value in the form via <em>Prefilled</em>, so new entries appear directly in the first column.</p></div><h2 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h2><p>Under <strong>Settings</strong>:</p><table tabindex="0"><thead><tr><th>Setting</th><th>Effect</th></tr></thead><tbody><tr><td><strong>Show card count</strong></td><td>Shows the number of cards per column</td></tr><tr><td><strong>Visible columns</strong></td><td>Hides individual columns — with <strong>All</strong> and <strong>None</strong> as shortcuts</td></tr></tbody></table><p>If there are no options, <em>No columns available</em> appears.</p><div class="tip custom-block"><p class="custom-block-title">Hiding what&#39;s finished</p><p>On long-lived boards, the <code>Done</code> column grows without bound. Hide it via <em>Visible columns</em> — the entries are retained, and the board stays manageable.</p><p>Alternatively, filter the view to the last few weeks.</p></div><h2 id="what-s-shown-on-a-card" tabindex="-1">What&#39;s shown on a card <a class="header-anchor" href="#what-s-shown-on-a-card" aria-label="Permalink to &quot;What&#39;s shown on a card&quot;">​</a></h2><p>Which fields appear on a card is configured per view. Almost every column type has its own card representation — text, select, multiple select, checkmark, links, user, files, signature, weblink, internal link.</p><p>Entries without a title appear as <em>Untitled entry</em>.</p><div class="tip custom-block"><p class="custom-block-title">Less is more</p><p>The advantage of a board is quick scannability. Three to four fields per card is usually enough: title, assignee, due date, maybe a priority. You&#39;ll see everything else when you open the entry.</p></div><h2 id="filter-sort-group" tabindex="-1">Filter, sort, group <a class="header-anchor" href="#filter-sort-group" aria-label="Permalink to &quot;Filter, sort, group&quot;">​</a></h2><p>Filters work as in any view: filtered-out entries don&#39;t appear on the board.</p><div class="tip custom-block"><p class="custom-block-title">One board per team</p><p>Instead of one overloaded board, multiple views with different filters pay off — &quot;My board&quot; with <code>Assignee</code> <code>is</code> <code>logged-in user</code>, &quot;This week&quot; with a date filter. All draw on the same data.</p></div><p>→ <a href="/en/ansichten/filtern-sortieren-gruppieren">Filtering, Sorting, Grouping</a></p><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><ul><li><a href="/en/ansichten/was-ist-eine-ansicht">What is a View</a></li><li><a href="/en/referenz/spaltentypen">Column type reference</a></li><li><a href="/en/ansichten/ansicht-teilen">Sharing a view</a></li></ul>',33)])])}const g=t(r,[["render",i]]);export{u as __pageData,g as default};
